<?= $this->extend('layout') ?>
<?= $this->section('content') ?>
<div class="page-head"><div><h1><?= $r['kind'] === 'opening' ? 'Opening stock' : 'Goods received' ?> <?= esc($r['number']) ?></h1><p class="sub"><?= esc($r['wh_code'] . ' ' . $r['wh_name']) ?> · <?= nice_date($r['received_on']) ?><?= $r['supplier'] ? ' · ' . esc($r['supplier']) : '' ?></p></div>
<div class="actions no-print"><?php if (can('inventory.move', (int) $r['warehouse_id'])): ?><a class="btn" href="<?= site_url('putaway') ?>">Put away</a><?php endif ?><a class="btn secondary" href="<?= site_url('labels/receipt/' . $r['id']) ?>">Labels</a><button class="btn secondary" data-print>Print GRN</button></div></div>
<section class="panel"><dl class="facts"><?php if ($r['po_number']): ?><dt>Purchase order</dt><dd><a href="<?= site_url('purchase-orders/' . $r['po_id']) ?>"><?= esc($r['po_number']) ?></a></dd><?php endif ?>
<?php if ($r['delivery_note']): ?><dt>Delivery note</dt><dd><?= esc($r['delivery_note']) ?></dd><?php endif ?><?php if ($r['carrier']): ?><dt>Brought by</dt><dd><?= esc($r['carrier']) ?></dd><?php endif ?>
<?php if ($r['currency'] !== '' || (float) $r['landed_pct'] > 0): ?><dt>Costs</dt><dd><?= $r['currency'] !== '' ? esc($r['currency']) . ' at ' . (float) $r['fx_rate'] . ' ' . esc(\App\Libraries\Master\Fx::home()) : esc(\App\Libraries\Master\Fx::home()) ?><?= (float) $r['landed_pct'] > 0 ? ', plus ' . (float) $r['landed_pct'] . '% landed cost' : '' ?>; unit costs below are the stock cost in <?= esc(\App\Libraries\Master\Fx::home()) ?></dd><?php endif ?>
<dt>Received by</dt><dd><?= esc($r['posted_name']) ?>, <?= local_time($r['posted_at']) ?></dd><?php if ($r['notes']): ?><dt>Notes</dt><dd><?= esc($r['notes']) ?></dd><?php endif ?></dl></section>
<div class="table-wrap"><table><thead><tr><th>Item</th><th>Description</th><th>Batch</th><th>Expiry</th><th>Bin</th><th class="num">Accepted</th><th class="num">Held</th><th class="num">Rejected</th><?php if (can('stock.view_cost')): ?><th class="num">Unit cost</th><th class="num">Value</th><?php endif ?></tr></thead><tbody>
<?php foreach ($lines as $l): $d = (int) $l['decimals'] ?><tr><td class="mono"><?= esc($l['sku']) ?></td><td><?= esc($l['name']) ?><?= $l['serials'] ? '<br><span class="muted small mono">' . esc(str_replace("\n", ', ', $l['serials'])) . '</span>' : '' ?><?= $l['reject_reason'] ? '<br><span class="small bad-text">Rejected: ' . esc($l['reject_reason']) . '</span>' : '' ?></td>
<td><?= $l['lot_id'] ? '<a href="' . site_url('lots/' . $l['lot_id']) . '">' . esc($l['lot_no']) . '</a>' : '' ?></td><td><?= nice_date($l['expiry_date']) ?></td><td class="mono"><?= esc($l['bin_code']) ?></td>
<td class="num"><?= qty($l['qty_accepted'], $d) ?></td><td class="num"><?= (float) $l['qty_quarantine'] ? qty($l['qty_quarantine'], $d) : '' ?></td><td class="num"><?= (float) $l['qty_rejected'] ? qty($l['qty_rejected'], $d) : '' ?></td>
<?php if (can('stock.view_cost')): ?><td class="num"><?= money($l['unit_cost'], false) ?><?= $l['unit_cost_fc'] !== null && $r['currency'] !== '' ? '<br><span class="muted small">' . esc($r['currency']) . ' ' . number_format((float) $l['unit_cost_fc'], 2) . '</span>' : '' ?></td><td class="num"><?= money(((float) $l['qty_accepted'] + (float) $l['qty_quarantine']) * (float) $l['unit_cost'], false) ?></td><?php endif ?></tr><?php endforeach ?>
</tbody><?php if (can('stock.view_cost')): ?><tfoot><tr><td colspan="9">Total</td><td class="num"><?= money($r['value']) ?></td></tr></tfoot><?php endif ?></table></div>
